// ATF-CP-UI-08: Account Not Linked UI
// Navigate to dashboard — should show AccountNotLinked for unlinked users
await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#dashboard');
await sn_atf.delay(3000);
var dashNotLinked = await screen.queryByText('Customer Account Not Linked');
var dashWelcome = await screen.queryByText(/Welcome,/i);
if (dashNotLinked) {
    expect(dashNotLinked).toBeVisible();
    var lockIcon = await screen.queryByText('\uD83D\uDD12');
    if (lockIcon) expect(lockIcon).toBeVisible();
    // Check orders page
    await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#orders');
    await sn_atf.delay(2000);
    var ordNotLinked = await screen.findByText('Customer Account Not Linked', { exact: false }, { timeout: 10000 });
    expect(ordNotLinked).toBeVisible();
    // Check profile page
    await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#profile');
    await sn_atf.delay(2000);
    var profNotLinked = await screen.findByText('Customer Account Not Linked', { exact: false }, { timeout: 10000 });
    expect(profNotLinked).toBeVisible();
    // Check delivery page
    await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#delivery');
    await sn_atf.delay(2000);
    var delNotLinked = await screen.findByText('Customer Account Not Linked', { exact: false }, { timeout: 10000 });
    expect(delNotLinked).toBeVisible();
    // Catalog should remain accessible
    await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#catalog');
    await sn_atf.delay(2000);
    var catalogHeading = await screen.findByText('Product Catalog', { exact: false }, { timeout: 10000 });
    expect(catalogHeading).toBeVisible();
} else if (dashWelcome) {
    // Current user IS linked — test passes with note
    expect(dashWelcome).toBeVisible();
}
